-- Isolated copy of the current production bootstrap/organization policies.
-- No auth users or test messages are created in the production project.
create role anon;create role authenticated;create schema auth;
create table auth.users(id uuid primary key,email text,raw_user_meta_data jsonb default '{}');
create function auth.uid() returns uuid language sql stable as $$select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid$$;
grant usage on schema auth to authenticated,anon;grant execute on function auth.uid() to authenticated,anon;
create table organizations(id uuid primary key default gen_random_uuid(),name text default 'Minha Agência',slug text unique,owner_user_id uuid references auth.users,created_at timestamptz default now());
create table organization_members(id uuid primary key default gen_random_uuid(),organization_id uuid references organizations,user_id uuid references auth.users,role text default 'member',created_at timestamptz default now(),unique(organization_id,user_id));
create function handle_new_user_org() returns trigger language plpgsql security definer set search_path='public' as $$begin insert into public.organizations(name,slug,owner_user_id) values('Minha Agência','org-'||replace(new.id::text,'-',''),new.id);return new;end$$;
create function handle_new_organization() returns trigger language plpgsql security definer set search_path='public' as $$begin if new.owner_user_id is not null then insert into public.organization_members(organization_id,user_id,role) values(new.id,new.owner_user_id,'owner') on conflict(organization_id,user_id) do nothing;end if;return new;end$$;
create trigger on_auth_user_created_create_org after insert on auth.users for each row execute function handle_new_user_org();
create trigger trg_new_organization_owner after insert on organizations for each row execute function handle_new_organization();
create function is_org_member(org uuid) returns boolean language sql stable security definer set search_path='public' as $$select exists(select 1 from public.organization_members where organization_id=org and user_id=auth.uid())$$;
create function is_org_admin(org uuid) returns boolean language sql stable security definer set search_path='public' as $$select exists(select 1 from public.organization_members where organization_id=org and user_id=auth.uid() and role in('owner','admin'))$$;
create function set_organization_id_from_user() returns trigger language plpgsql security definer set search_path='public' as $$begin if new.organization_id is null then select organization_id into new.organization_id from public.organization_members where user_id=new.user_id order by created_at limit 1;end if;return new;end$$;
alter table organizations enable row level security;alter table organization_members enable row level security;
create policy members_select_org on organizations for select using(is_org_member(id));create policy users_create_org on organizations for insert with check(owner_user_id=auth.uid());create policy admins_update_org on organizations for update using(is_org_admin(id)) with check(is_org_admin(id));
create policy members_select_memberships on organization_members for select using(is_org_member(organization_id));create policy admins_manage_memberships on organization_members for insert with check(is_org_admin(organization_id));create policy admins_update_memberships on organization_members for update using(is_org_admin(organization_id)) with check(is_org_admin(organization_id));create policy admins_delete_memberships on organization_members for delete using(is_org_admin(organization_id));
grant select,insert,update on organizations to authenticated;grant select,insert,update,delete on organization_members to authenticated;
create table profiles(user_id uuid primary key references auth.users,id uuid default gen_random_uuid(),onboarding_completed boolean default false,notif_email boolean default false,notif_email_destino text,notif_config jsonb default '{}',created_at timestamptz default now());
alter table profiles enable row level security;create policy users_select_own_profile on profiles for select using(auth.uid()=user_id);create policy users_insert_own_profile on profiles for insert with check(auth.uid()=user_id);create policy users_update_own_profile on profiles for update using(auth.uid()=user_id);
grant select,insert,update on profiles to authenticated;
create table clients(id uuid primary key default gen_random_uuid(),user_id uuid,organization_id uuid references organizations,name text,status text default 'Ativo',monthly_fee numeric default 0,phone text default '',created_at timestamptz default now());
create table operational_tasks(id uuid primary key default gen_random_uuid(),user_id uuid,organization_id uuid references organizations,title text,description text default '',status text default 'pendente',priority text default 'média',start_date date,end_date date,client_id uuid,closed_at timestamptz,recurrence text default 'none',recurrence_interval int default 1,recurrence_days jsonb default '[]',assignee_name text default '',assignee_user_id uuid,area text default '',recurrence_of uuid,recurrence_anchor date,created_at timestamptz default now());
create table mensalidades(id uuid primary key default gen_random_uuid(),user_id uuid,organization_id uuid references organizations,cliente_id uuid,valor numeric,status text,vencimento date,created_at timestamptz default now());
create table transacoes(id uuid primary key default gen_random_uuid(),user_id uuid,organization_id uuid references organizations,tipo text,valor numeric,data date,created_at timestamptz default now());
do $$declare t text;begin foreach t in array array['clients','operational_tasks','mensalidades','transacoes'] loop execute format('alter table %I enable row level security',t);execute format('create policy org_members_all on %I for all using(is_org_member(organization_id)) with check(is_org_member(organization_id))',t);execute format('create trigger trg_set_org before insert on %I for each row execute function set_organization_id_from_user()',t);execute format('grant select,insert,update,delete on %I to authenticated',t);end loop;end$$;
